?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel · Bruma Café</title><link rel="stylesheet" href="../assets/styles.css"></head><body><header class="top"><nav class="wrap nav"><a class="brand" href="../index.php">bruma<span>.</span>café</a><div class="links"><a href="../index.php">Ver web</a><a href="logout.php">Salir</a></div></nav></header><main class="wrap admin-main"><div class="admin-bar"><div><div class="eyebrow">Área privada</div><h1 style="font-size:42px;color:var(--green);margin:5px 0">Panel de administración</h1></div><a href="producto.php" class="btn">+ Nuevo producto</a></div><section class="panel"><h2>Productos (<?= count($productos) ?>)</h2><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Visible</th><th>Acciones</th></tr></thead><tbody><?php foreach ($productos as $producto): ?><tr><td><?= e($producto['nombre']) ?></td><td><?= e($producto['categoria']) ?></td><td>$<?= number_format((float)$producto['precio'],2) ?></td><td><?= $producto['activo'] ? 'Sí' : 'No' ?></td><td><div class="actions"><a class="btn small" href="producto.php?id=<?= (int)$producto['id'] ?>">Editar</a><form method="post" action="eliminar.php" onsubmit="return confirm('¿Eliminar este producto?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$producto['id'] ?>"><button class="btn warn small">Eliminar</button></form></div></td></tr><?php endforeach; ?></tbody></table></section><section class="panel"><h2>Pedidos recientes (<?=count($pedidos)?>)</h2><p class="muted">Pedidos de demostración. No son ventas reales.</p><table><thead><tr><th>N.º</th><th>Cliente</th><th>Teléfono</th><th>Total</th><th>Estado</th><th>Fecha</th><th>Detalle</th></tr></thead><tbody><?php foreach($pedidos as $pedido): ?><tr><td>#<?=(int)$pedido['id']?></td><td><?=e($pedido['cliente_nombre'])?></td><td><?=e($pedido['cliente_telefono'])?></td><td>$<?=number_format((float)$pedido['total'],2)?></td><td><?=e($pedido['estado'])?></td><td><?=e($pedido['creado_en'])?></td><td><a href="pedido.php?id=<?=(int)$pedido['id']?>">Ver / cambiar estado</a></td></tr><?php endforeach; ?></tbody></table></section><section class="panel"><h2>Mensajes recientes (<?= count($mensajes) ?>)</h2><table><thead><tr><th>Nombre</th><th>Correo</th><th>Mensaje</th><th>Fecha</th></tr></thead><tbody><?php foreach ($mensajes as $mensaje): ?><tr><td><?= e($mensaje['nombre']) ?></td><td><?= e($mensaje['correo']) ?></td><td><?= nl2br(e($mensaje['mensaje'])) ?></td><td><?= e($mensaje['creado_en']) ?></td></tr><?php endforeach; ?></tbody></table></section></main></body></html>
